-- BACKUP of the TEST data purged on 2026-09-29 from project qohoqbapevrcjqxbstxi.
-- Decision: docs/decisions/0234-2026-09-29-test-data-purge.md
-- Purge script: docs/data-corrections/2026-09-29_test_purge.sql
--
-- This file RESTORES the purged rows. Running it puts back exactly the rows
-- the purge removed (verified in a rolled-back dry run: after purge +
-- restore, the md5 of every one of these 18 tables plus partiya_counter,
-- serial_counter, owners and profiles was identical to before the purge).
--
-- Form: one INSERT per table, rows carried as a JSON array and expanded with
-- jsonb_populate_recordset. Each payload is the table's rows as
-- jsonb_agg(to_jsonb(row) order by to_jsonb(row)::text); the md5 in each
-- header comment is md5() of exactly that text, the same md5 the purge
-- script asserted before deleting. gate_weighings.net_kg and
-- raw_dispatch_lines.net_kg are generated columns, so they are left out of
-- the payload and recomputed on insert.
--
-- Triggers: two BEFORE/AFTER INSERT triggers would change data on restore
-- and are disabled for the duration of the transaction:
--   * kirim_lines_assign_partiya_no -- would overwrite partiya_no with a new
--     number and bump partiya_counter;
--   * lab_results_audit             -- would write duplicate audit_log rows
--     (the original audit rows are restored from this file).
-- The remaining triggers (enforce_serial_process, prevent_dual_process_serial,
-- the two overdraw checks) validate only and stay on.
-- session_replication_role = replica is NOT available to the postgres role
-- on this project (42501), hence ALTER TABLE ... DISABLE TRIGGER.
--
-- Not included (never deleted): storage objects. The 57 photos these rows
-- referenced (gate, pile) were left in their buckets, so restored rows
-- resolve to the same files.
--
-- Rows: kirim_orders 31, kirim_lines 38, storage_intake 22, wash_cycles 10,
-- moyka_sends 2, rezka_cycles 23, rezka_sends 23, finished_pallets 41,
-- lab_results 17, rezka_kn_draws 8, chiqim_requests 11, chiqim_lines 17,
-- gate_weighings 13, chiqim_pallet_consumption 5, raw_dispatch_lines 5,
-- chiqim_line_raw_serials 6, notes 8, audit_log 24  (total 304).

begin;

alter table public.kirim_lines disable trigger kirim_lines_assign_partiya_no;
alter table public.lab_results disable trigger lab_results_audit;

